{{define "content"}}
<div class="space-y-8">
  <!-- Hero Section -->
  <div class="text-center space-y-4 py-8">
    <h1
      class="text-5xl font-bold bg-gradient-to-r from-green-400 via-emerald-400 to-green-500 bg-clip-text text-transparent animate-pulse-slow">
      Health Checks
    </h1>
    <p class="text-gray-400 text-lg max-w-2xl mx-auto">
      Monitor and control Kubernetes liveness and readiness probes for this pod
    </p>
  </div>

  <!-- Liveness Check Card -->
  <div class="glass rounded-2xl p-6 border border-green-500/20">
    <div class="flex flex-col md:flex-row md:items-center md:justify-between gap-6">
      <div class="flex items-center space-x-4">
        <div class="w-16 h-16 bg-gradient-to-br from-green-500 to-emerald-500 rounded-2xl flex items-center justify-center">
          <svg class="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
              d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z">
            </path>
          </svg>
        </div>
        <div>
          <h3 class="text-xl font-semibold text-white">Liveness Probe <span class="text-sm font-normal text-gray-400 ml-2">(/healthz)</span></h3>
          <p class="text-sm text-gray-400 mt-1">Kubernetes liveness probe - determines if pod should be restarted</p>
        </div>
      </div>

      <div class="flex items-center space-x-6">
        <!-- Status Indicator -->
        <div class="flex items-center space-x-3">
          <div id="liveness-indicator" class="w-4 h-4 rounded-full bg-green-500 animate-pulse" title="Alive"></div>
          <span id="liveness-text" class="text-sm font-medium text-green-400">Alive</span>
          <span id="liveness-code-badge" class="px-2 py-1 text-xs font-mono bg-green-500/20 text-green-300 rounded">200</span>
        </div>

        <!-- Toggle Switch -->
        <label class="toggle-switch relative inline-flex items-center cursor-pointer" title="Toggle Liveness (Alive/Dead)">
          <input type="checkbox" id="liveness-switch" class="sr-only peer" checked aria-label="Liveness probe status">
          <div class="toggle-track w-14 h-8 bg-gray-700 rounded-full border border-gray-600 transition-colors duration-300 peer-checked:bg-green-500 peer-checked:border-green-500"></div>
          <div class="toggle-thumb absolute w-6 h-6 bg-white rounded-full shadow-lg transition-transform duration-300 transform peer-checked:translate-x-6"></div>
          <div class="absolute inset-0 flex items-center justify-between px-1 pointer-events-none">
            <span class="text-xs font-medium text-gray-500 peer-checked:opacity-0 transition-opacity">DEAD</span>
            <span class="text-xs font-medium text-gray-500 opacity-0 peer-checked:opacity-100 transition-opacity text-green-400">ALIVE</span>
          </div>
        </label>
      </div>
    </div>
  </div>

  <!-- Readiness Check Card -->
  <div class="glass rounded-2xl p-6 border border-emerald-500/20">
    <div class="flex flex-col md:flex-row md:items-center md:justify-between gap-6">
      <div class="flex items-center space-x-4">
        <div class="w-16 h-16 bg-gradient-to-br from-emerald-500 to-teal-500 rounded-2xl flex items-center justify-center">
          <svg class="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
              d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"></path>
          </svg>
