<script>
// Health check endpoints
const HEALTHZ_URL = '/healthz';
const HEALTHZR_URL = '/healthzr';

// State tracking
let livenessAlive = true;
let readinessReady = true;

// Update UI for liveness
function updateLivenessUI(alive, statusCode) {
  livenessAlive = alive;
  const statusEl = document.getElementById('liveness-indicator');
  const textEl = document.getElementById('liveness-text');
  const codeEl = document.getElementById('liveness-code-badge');
  const switchEl = document.getElementById('liveness-switch');

  if (alive) {
    statusEl.className = 'w-4 h-4 rounded-full bg-green-500 animate-pulse';
    textEl.className = 'text-sm font-medium text-green-400';
    textEl.textContent = 'Alive';
    codeEl.textContent = statusCode || 200;
    codeEl.className = 'px-2 py-1 text-xs font-mono bg-green-500/20 text-green-300 rounded';
    switchEl.checked = true;
  } else {
    statusEl.className = 'w-4 h-4 rounded-full bg-red-500';
    textEl.className = 'text-sm font-medium text-red-400';
    textEl.textContent = 'Dead';
    codeEl.textContent = statusCode || 500;
    codeEl.className = 'px-2 py-1 text-xs font-mono bg-red-500/20 text-red-300 rounded';
    switchEl.checked = false;
  }
}

// Update UI for readiness
function updateReadinessUI(ready, statusCode) {
  readinessReady = ready;
  const statusEl = document.getElementById('readiness-indicator');
  const textEl = document.getElementById('readiness-text');
  const codeEl = document.getElementById('readiness-code-badge');
  const switchEl = document.getElementById('readiness-switch');

  if (ready) {
    statusEl.className = 'w-4 h-4 rounded-full bg-emerald-500 animate-pulse';
    textEl.className = 'text-sm font-medium text-emerald-400';
    textEl.textContent = 'Ready';
    codeEl.textContent = statusCode || 200;
    codeEl.className = 'px-2 py-1 text-xs font-mono bg-emerald-500/20 text-emerald-300 rounded';
    switchEl.checked = true;
  } else {
    statusEl.className = 'w-4 h-4 rounded-full bg-red-500';
    textEl.className = 'text-sm font-medium text-red-400';
    textEl.textContent = 'Not Ready';
    codeEl.textContent = statusCode || 503;
    codeEl.className = 'px-2 py-1 text-xs font-mono bg-red-500/20 text-red-300 rounded';
    switchEl.checked = false;
  }
}

// Send request to health endpoint
async function sendHealthRequest(url, action) {
  try {
    const response = await fetch(`${url}?${action}`, { method: 'GET' });
    return { ok: response.ok, status: response.status };
  } catch (err) {
    console.error('Health request failed:', err);
    return { ok: false, status: 0, error: err.message };
  }
}

// Check current status
async function checkLiveness() {
  try {
    const response = await fetch(HEALTHZ_URL);
    updateLivenessUI(response.ok, response.status);
  } catch (err) {
    console.error('Liveness check failed:', err);
    updateLivenessUI(false, 0);
  }
}

async function checkReadiness() {
  try {
    const response = await fetch(HEALTHZR_URL);
    updateReadinessUI(response.ok, response.status);
  } catch (err) {
    console.error('Readiness check failed:', err);
    updateReadinessUI(false, 0);
  }
}

// Toggle liveness via switch
async function toggleLiveness() {
  const switchEl = document.getElementById('liveness-switch');
  const action = switchEl.checked ? 'live' : 'die';

  switchEl.disabled = true;
  const result = await sendHealthRequest(HEALTHZ_URL, action);

  if (result.ok) {
    updateLivenessUI(switchEl.checked, result.status);
  } else {
    switchEl.checked = !switchEl.checked;
    console.error('Failed to toggle liveness:', result);
  }
  switchEl.disabled = false;
}

// Toggle readiness via switch
async function toggleReadiness() {
  const switchEl = document.getElementById('readiness-switch');
  const action = switchEl.checked ? 'live' : 'die';

  switchEl.disabled = true;
  const result = await sendHealthRequest(HEALTHZR_URL, action);

  if (result.ok) {
    updateReadinessUI(switchEl.checked, result.status);
  } else {
    switchEl.checked = !switchEl.checked;
    console.error('Failed to toggle readiness:', result);
  }
  switchEl.disabled = false;
}

// Button handlers
async function setLivenessLive() {
  const btn = document.getElementById('liveness-live-btn');
  btn.disabled = true;
  const result = await sendHealthRequest(HEALTHZ_URL, 'live');
  if (result.ok) updateLivenessUI(true, result.status);
  btn.disabled = false;
}

async function setLivenessDie() {
  const btn = document.getElementById('liveness-die-btn');
  btn.disabled = true;
  const result = await sendHealthRequest(HEALTHZ_URL, 'die');
  if (result.ok) updateLivenessUI(false, result.status);
  btn.disabled = false;
}

async function setReadinessLive() {
  const btn = document.getElementById('readiness-live-btn');
  btn.disabled = true;
  const result = await sendHealthRequest(HEALTHZR_URL, 'live');
  if (result.ok) updateReadinessUI(true, result.status);
  btn.disabled = false;
}

async function setReadinessDie() {
  const btn = document.getElementById('readiness-die-btn');
  btn.disabled = true;
  const result = await sendHealthRequest(HEALTHZR_URL, 'die');
  if (result.ok) updateReadinessUI(false, result.status);
  btn.disabled = false;
}

// Event listeners
document.addEventListener('DOMContentLoaded', () => {
  // Initial status check
  checkLiveness();
  checkReadiness();

  // Switch listeners
  document.getElementById('liveness-switch').addEventListener('change', toggleLiveness);
  document.getElementById('readiness-switch').addEventListener('change', toggleReadiness);

  // Button listeners
  document.getElementById('liveness-live-btn').addEventListener('click', setLivenessLive);
  document.getElementById('liveness-die-btn').addEventListener('click', setLivenessDie);
  document.getElementById('liveness-check-btn').addEventListener('click', checkLiveness);
  document.getElementById('readiness-live-btn').addEventListener('click', setReadinessLive);
  document.getElementById('readiness-die-btn').addEventListener('click', setReadinessDie);
  document.getElementById('readiness-check-btn').addEventListener('click', checkReadiness);

  // Periodic status check (every 10 seconds)
  setInterval(() => {
    checkLiveness();
    checkReadiness();
  }, 10000);
});
</script>
