@import url(//fonts.googleapis.com/css?family=Roboto:300,400,500,700|Material+Icons);

/* Healthz Toggle Switch Styles */
/* Matches HTML structure in healthz.html with .toggle-switch label */
.toggle-switch {
  display: inline-flex;
  align-items: center;
  cursor: pointer;
}

.toggle-switch input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-track {
  width: 3.5rem; /* 56px = w-14 */
  height: 2rem;   /* 32px = h-8 */
  background-color: #374151; /* bg-gray-700 */
  border: 1px solid #4b5563; /* border-gray-600 */
  border-radius: 9999px; /* rounded-full */
  transition: background-color 0.3s, border-color 0.3s;
  position: relative;
}

.toggle-thumb {
  width: 1.5rem;  /* 24px = w-6 */
  height: 1.5rem; /* 24px = h-6 */
  background-color: white;
  border-radius: 9999px; /* rounded-full */
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05); /* shadow-lg */
  transition: transform 0.3s;
  position: absolute;
  top: 0.25rem; /* 4px */
  left: 0.25rem; /* 4px */
}

.toggle-switch input:checked ~ .toggle-track {
  background-color: #22c55e; /* bg-green-500 */
  border-color: #22c55e; /* border-green-500 */
}

.toggle-switch input:checked ~ .toggle-thumb {
  transform: translateX(1.5rem); /* 24px = translate-x-6 */
}

/* Readiness toggle - emerald color */
.toggle-switch input:checked ~ .toggle-track.readiness-track {
  background-color: #10b981; /* bg-emerald-500 */
  border-color: #10b981; /* border-emerald-500 */
}

/* Text labels */
.toggle-labels {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 0.25rem; /* px-1 */
  pointer-events: none;
}

.toggle-label-off,
.toggle-label-on {
  font-size: 0.75rem; /* text-xs */
  font-weight: 500; /* font-medium */
  color: #9ca3af; /* text-gray-500 */
  transition: opacity 0.3s;
}

.toggle-label-on {
  opacity: 0;
  color: #4ade80; /* text-green-400 */
}

.toggle-switch input:checked ~ .toggle-labels .toggle-label-off {
  opacity: 0;
}

.toggle-switch input:checked ~ .toggle-labels .toggle-label-on {
  opacity: 1;
}

/* Readiness specific labels */
.toggle-label-readiness-off {
  color: #9ca3af; /* text-gray-500 */
}

.toggle-label-readiness-on {
  color: #34d399; /* text-emerald-400 */
}


